def process(all_fraud, all_identity) -> pd.DataFrame:
    merged = all_identity.merge(all_fraud[['Metropolitan Area', 'Fraud_Reports']], on='Metropolitan Area', how='inner')
    merged['identity_exceeds_fraud'] = merged['Identity_Reports'] > merged['Fraud_Reports']
    result = merged[merged['identity_exceeds_fraud']][['Metropolitan Area', 'Identity_Reports', 'Fraud_Reports']]
    return result.reset_index(drop=True)
